var L_user_data_js=globalThis.I18n||{t:(s,v)=>v?s.replace(/\{(\w+)\}/g,(m,k)=>v[k]??m):s,error:s=>s,locale:undefined};
/* Explicit local folder access; writes commit only after writable.close succeeds. */
(function(root){
 const C=UserDataCore,E=id=>document.getElementById(id);
 let config={},loading=true,revision=0,timer,working=false,pending=null,restoreBusy=false,summaryEpoch=0,permissionState='unknown';
 const fileExclusive=fn=>navigator.locks?navigator.locks.request('aka-user-file-v1',fn):fn();
 function status(text,error=false){E('dataStatus').textContent=text;E('dataStatus').dataset.error=String(error);E('dataSidebarStatus').textContent=error?text:'';E('dataSidebarStatus').hidden=!error}
 function ui(){const support=typeof root.showDirectoryPicker==='function';E('dataFolder').textContent=config.folder?.name||L_user_data_js.t("선택한 폴더 없음");E('dataChooseFolder').textContent=config.folder?L_user_data_js.t("폴더 변경"):L_user_data_js.t("폴더 선택");E('dataChooseFolder').disabled=loading||working||!support;E('dataReconnect').hidden=!config.folder;E('dataReconnect').disabled=working;E('dataAuto').checked=!!config.auto;E('dataAuto').disabled=working||!support||!config.folder;E('dataManual').disabled=loading||working;E('dataLoad').disabled=loading||working;E('dataLastSaved').textContent=config.lastSaved?new Date(config.lastSaved).toLocaleString(L_user_data_js.locale):L_user_data_js.t("아직 저장하지 않음");E('dataLastBackup').textContent=config.lastBackup?new Date(config.lastBackup).toLocaleString(L_user_data_js.locale):L_user_data_js.t("아직 저장하지 않음");E('dataPermission').textContent=!config.folder?'':permissionState==='granted'?L_user_data_js.t("쓰기 허용됨"):L_user_data_js.t("권한 확인 필요 · 다시 연결");E('dataSupport').textContent=support?L_user_data_js.t("선택한 폴더에 저장합니다. 브라우저는 전체 경로 대신 폴더 이름을 표시합니다."):L_user_data_js.t("이 환경은 폴더 자동 저장을 지원하지 않습니다. 수동 백업·불러오기를 사용하세요.")}
 async function refresh(){const token=++summaryEpoch;try{config=await C.metaGet('config')||config;const p=await C.exclusive(C.snapshot);if(token!==summaryEpoch)return;for(const [key,value]of Object.entries(C.summary(p)))E('dataCount-'+key).textContent=key==='settings'?(value?L_user_data_js.t("저장됨"):L_user_data_js.t("기본값")):value.toLocaleString(L_user_data_js.locale);ui()}catch(e){status(L_user_data_js.t("데이터 요약 실패: ")+L_user_data_js.error(e.message),true)}}
 async function permission(handle,ask=false){let p=await handle.queryPermission({mode:'readwrite'});if(p!=='granted'&&ask)p=await handle.requestPermission({mode:'readwrite'});permissionState=p;if(p!=='granted')throw Error(L_user_data_js.t("저장 폴더 권한이 필요합니다. 설정에서 다시 연결해 주세요."))}
 async function existing(folder){try{const h=await folder.getFileHandle('AKA-Sheet-auto.json');const f=await h.getFile();if(f.size>100*1024*1024)throw Error(L_user_data_js.t("기존 자동 저장 파일이 너무 큽니다."));return await f.text()}catch(e){if(e.name==='NotFoundError')return null;throw e}}
 async function writeFile(folder,name,text){const file=await folder.getFileHandle(name,{create:true}),w=await file.createWritable();try{await w.write(text);await w.close()}catch(e){try{await w.abort()}catch{}throw e}}
 function schedule(){clearTimeout(timer);if(!loading&&config.auto)timer=setTimeout(saveAuto,1800)}
 function changed(broadcast=true){revision++;if(!loading&&config.auto&&config.folder&&!working)status(L_user_data_js.t("변경 사항을 자동 저장할 예정입니다."));schedule();if(broadcast){try{localStorage.setItem('aka.user-data.changed',crypto.randomUUID())}catch{}}}
 async function saveAuto(){if(loading||!config.auto||!config.folder)return;if(working){schedule();return}working=true;ui();let again=false;try{await fileExclusive(async()=>{config=await C.metaGet('config')||config;if(!config.auto||!config.folder)return;await permission(config.folder);const previous=await existing(config.folder);if(previous!==null&&(!config.fileHash||await C.hash(previous)!==config.fileHash))throw Error(L_user_data_js.t("자동 저장 파일이 외부에서 변경되었습니다. 백업 불러오기로 확인하세요."));const rev=revision,p=await C.exclusive(C.snapshot),dataHash=await C.hash(p);if(previous!==null&&config.dataHash===dataHash){status(L_user_data_js.t("모든 변경 사항이 저장되었습니다."));return}if(revision===0&&previous!==null){const old=C.summary((await C.decode(previous)).data),now=C.summary(p);if(old.marks+old.text+old.drawing+old.words+old.positions+(old.books||0)+(old.settings?1:0)>0&&now.marks+now.text+now.drawing+now.words+now.positions+(now.books||0)+(now.settings?1:0)===0)throw Error(L_user_data_js.t("내부 데이터가 비어 있습니다. 자동 파일을 보호했으니 백업 불러오기로 복원하세요."))}const text=await C.encode(p);await writeFile(config.folder,'AKA-Sheet-auto.json',text);config={...config,fileHash:await C.hash(text),dataHash,lastSaved:Date.now()};await C.metaPut('config',config);again=rev!==revision;status(again?L_user_data_js.t("추가 변경 사항을 저장할 예정입니다."):L_user_data_js.t("모든 변경 사항이 저장되었습니다."))})}catch(e){status(L_user_data_js.t("자동 저장 실패: ")+L_user_data_js.error(e.message)+L_user_data_js.t(" 브라우저 내부 데이터는 유지됩니다."),true)}finally{working=false;ui();if(again)schedule()}}
 function preview(v,folder=null,original=null){pending={v,folder,original};const s=C.summary(v.data);E('dataRestoreCounts').textContent=L_user_data_js.t("형광펜 ")+s.marks+L_user_data_js.t("개 · 텍스트 메모 ")+s.text+L_user_data_js.t("개 · 그리기 ")+s.drawing+L_user_data_js.t("개 · 단어장 ")+s.books+L_user_data_js.t("개 · 단어 ")+s.words+L_user_data_js.t("개 · 읽기 위치 ")+s.positions+L_user_data_js.t("권");E('dataRestoreTime').textContent=L_user_data_js.t("백업 시각: ")+(Number.isNaN(Date.parse(v.createdAt))?L_user_data_js.t("알 수 없음"):new Date(v.createdAt).toLocaleString(L_user_data_js.locale));E('dataRestorePreferences').checked=true;E('dataRestoreStatus').textContent=folder?L_user_data_js.t("이 폴더에는 자동 저장 파일이 있습니다. 불러온 뒤 폴더를 연결합니다."):'';E('dataRestoreConfirm').showModal()}
 async function chooseFolder(){if(working)return;try{const folder=await root.showDirectoryPicker({id:'aka-user-data',mode:'readwrite',startIn:'documents'});await permission(folder,true);working=true;ui();await fileExclusive(async()=>{config=await C.metaGet('config')||config;if(config.folder&&await folder.isSameEntry(config.folder)){status(L_user_data_js.t("저장 폴더를 다시 연결했습니다."));return}const text=await existing(folder);if(text!==null){preview(await C.decode(text),folder,text);return}const p=await C.exclusive(C.snapshot),textNew=await C.encode(p);await writeFile(folder,'AKA-Sheet-auto.json',textNew);config={folder,auto:!!config.auto,lastBackup:config.lastBackup,lastSaved:Date.now(),fileHash:await C.hash(textNew),dataHash:await C.hash(p)};await C.metaPut('config',config);status(L_user_data_js.t("새 폴더에 현재 데이터를 저장했습니다. 기존 폴더의 파일은 유지됩니다."));changed()})}catch(e){if(e.name!=='AbortError')status(L_user_data_js.t("폴더 연결 실패: ")+L_user_data_js.error(e.message),true)}finally{working=false;ui()}}
 async function reconnect(){if(working||!config.folder)return;try{await permission(config.folder,true);status(L_user_data_js.t("폴더 쓰기 권한을 확인했습니다."));schedule()}catch(e){status(L_user_data_js.error(e.message),true)}}
 async function setAuto(){const on=E('dataAuto').checked;try{if(on)await permission(config.folder,true);await fileExclusive(async()=>{config=await C.metaGet('config')||config;config.auto=on;await C.metaPut('config',config)});if(on){status(L_user_data_js.t("자동 저장을 켰습니다."));schedule()}else{clearTimeout(timer);status(L_user_data_js.t("자동 저장을 껐습니다."))}changed()}catch(e){status(L_user_data_js.error(e.message),true)}ui()}
 const stamp=()=>new Date().toISOString().replace(/[:.]/g,'-');
 function download(text,name){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}
 async function manual(){if(working)return;const folder=config.folder;try{if(folder)await permission(folder,true);working=true;ui();const p=await C.exclusive(C.snapshot),text=await C.encode(p),name='AKA-Sheet-backup-'+stamp()+'-'+crypto.randomUUID().slice(0,8)+'.json';await fileExclusive(async()=>{if(folder)await writeFile(folder,name,text);else download(text,name);config=await C.metaGet('config')||config;config.lastBackup=Date.now();await C.metaPut('config',config)});status(folder?L_user_data_js.t("수동 백업을 선택한 폴더에 저장했습니다."):L_user_data_js.t("백업 파일을 다운로드했습니다."))}catch(e){status(L_user_data_js.t("수동 백업 실패: ")+L_user_data_js.error(e.message),true)}finally{working=false;ui()}}
 async function loadFile(file){if(!file||working)return;working=true;ui();try{if(file.size>100*1024*1024)throw Error(L_user_data_js.t("백업 파일은 100MB 이하만 지원합니다."));preview(await C.decode(await file.text()))}catch(e){status(L_user_data_js.t("백업 불러오기 실패: ")+L_user_data_js.error(e.message),true)}finally{working=false;ui();E('dataImportFile').value=''}}
 async function restore(){if(!pending||restoreBusy)return;restoreBusy=working=true;const chosen=pending;E('dataRestoreApply').disabled=E('dataRestoreCancel').disabled=true;ui();try{await fileExclusive(async()=>{if(chosen.folder&&await existing(chosen.folder)!==chosen.original)throw Error(L_user_data_js.t("선택 이후 파일이 변경되었습니다. 다시 선택하세요."));const apply=E('dataRestorePreferences').checked;await C.merge(chosen.v.data,apply);if(chosen.folder){/* Preserve the original automatic file; merged data is saved only after explicit auto enable. */config={folder:chosen.folder,auto:false,lastSaved:Date.parse(chosen.v.createdAt)||null,fileHash:await C.hash(chosen.original),dataHash:await C.hash(chosen.v.data)};await C.metaPut('config',config)}});changed();E('dataRestoreConfirm').close();pending=null;status(L_user_data_js.t("백업을 합쳤습니다. 앱을 다시 열어 적용하세요."));E('dataReload').hidden=false;await refresh();location.reload()}catch(e){E('dataRestoreStatus').textContent=L_user_data_js.t("복원 실패: ")+L_user_data_js.error(e.message)}finally{restoreBusy=working=false;E('dataRestoreApply').disabled=E('dataRestoreCancel').disabled=false;ui()}}
 function wrap(object,methods){for(const key of methods){const fn=object[key];object[key]=(...args)=>C.exclusive(async()=>{const r=await fn(...args);changed();return r})}}
 async function init(){wrap(HighlightStore,['put','patch','remove']);wrap(NoteStore,['put','putPage','remove']);wrap(VocabularyStore,['saveBook','saveEntry','removeEntry','removeBook','ensureDefault']);wrap(ImageBookRegistry,['register','position']);E('dataChooseFolder').onclick=chooseFolder;E('dataReconnect').onclick=reconnect;E('dataAuto').onchange=()=>setAuto();E('dataManual').onclick=manual;E('dataLoad').onclick=()=>E('dataImportFile').click();E('dataImportFile').onchange=e=>loadFile(e.target.files[0]);E('dataRefresh').onclick=refresh;E('dataRestoreApply').onclick=restore;E('dataRestoreCancel').onclick=()=>{if(!restoreBusy){pending=null;E('dataRestoreConfirm').close()}};E('dataRestoreConfirm').addEventListener('cancel',e=>{if(restoreBusy)e.preventDefault();else pending=null});E('dataReload').onclick=()=>location.reload();window.addEventListener('storage',async e=>{if(e.key==='aka.user-data.changed'){config=await C.metaGet('config')||{};changed(false);ui()}});document.addEventListener('visibilitychange',()=>{if(document.hidden)saveAuto()});ui();try{config=await C.metaGet('config')||{};if(config.folder)permissionState=await config.folder.queryPermission({mode:'readwrite'});status(config.folder?L_user_data_js.t("저장 폴더를 기억하고 있습니다. 변경 시 자동 저장하며, 권한이 필요하면 다시 연결하세요."):L_user_data_js.t("저장 폴더를 선택하거나 수동 백업을 저장하세요."))}catch(e){status(L_user_data_js.t("폴더 설정 불러오기 실패: ")+L_user_data_js.error(e.message),true)}loading=false;ui();schedule()}
 root.UserData={changed,refresh,saveAuto,writeFile,init};
 init();
})(globalThis);
